from typing import List
from sortedcontainers import SortedList

class Solution:
    def longestCommonPrefix(self, words: List[str], k: int) -> List[int]:
        n = len(words)
        if n - 1 < k:
            return [0] * n

        trie_children = [[0] * 26]
        trie_count = [0]
        trie_depth = [0]

        for word in words:
            curr = 0
            trie_count[0] += 1
            for char in word:
                idx = ord(char) - 97
                if not trie_children[curr][idx]:
                    trie_children[curr][idx] = len(trie_children)
                    trie_children.append([0] * 26)
                    trie_count.append(0)
                    trie_depth.append(trie_depth[curr] + 1)
                curr = trie_children[curr][idx]
                trie_count[curr] += 1

        best_all = 0
        freq = {}
        depths = SortedList()

        for i in range(1, len(trie_count)):
            c = trie_count[i]
            d = trie_depth[i]
            if c >= k + 1:
                if d > best_all:
                    best_all = d
            elif c == k:
                if freq.get(d, 0) == 0:
                    depths.add(d)
                    freq[d] = 1
                else:
                    freq[d] += 1

        ans = []
        for word in words:
            curr = 0
            path_k_nodes = []

            for char in word:
                idx = ord(char) - 97
                curr = trie_children[curr][idx]
                if trie_count[curr] == k:
                    path_k_nodes.append(trie_depth[curr])

            for d in path_k_nodes:
                freq[d] -= 1
                if freq[d] == 0:
                    depths.remove(d)

            cur_max = depths[-1] if depths else 0
            ans.append(max(best_all, cur_max))

            for d in path_k_nodes:
                if freq[d] == 0:
                    depths.add(d)
                freq[d] += 1

        return ans
